    public var localDate: String
    public var value: Double?
    public var verificationStatus: VerificationStatusFfi

    // Default memberwise initializers are never public by default, so we
    // declare one manually.
    public init(id: String, habitId: String, timestampUtc: Int64, tzOffsetMinutes: Int32, localDate: String, value: Double?, verificationStatus: VerificationStatusFfi) {
        self.id = id
        self.habitId = habitId
        self.timestampUtc = timestampUtc
        self.tzOffsetMinutes = tzOffsetMinutes
        self.localDate = localDate
        self.value = value
        self.verificationStatus = verificationStatus
    }
}



extension CheckInRecordFfi: Equatable, Hashable {
    public static func ==(lhs: CheckInRecordFfi, rhs: CheckInRecordFfi) -> Bool {
        if lhs.id != rhs.id {
            return false
        }
        if lhs.habitId != rhs.habitId {
            return false
        }
        if lhs.timestampUtc != rhs.timestampUtc {
            return false
        }
        if lhs.tzOffsetMinutes != rhs.tzOffsetMinutes {
            return false
        }
        if lhs.localDate != rhs.localDate {
            return false
        }
        if lhs.value != rhs.value {
            return false
        }
        if lhs.verificationStatus != rhs.verificationStatus {
            return false
        }
        return true
    }

    public func hash(into hasher: inout Hasher) {
        hasher.combine(id)
        hasher.combine(habitId)
        hasher.combine(timestampUtc)
        hasher.combine(tzOffsetMinutes)
        hasher.combine(localDate)
        hasher.combine(value)
        hasher.combine(verificationStatus)
    }
}


